<template><AppLayout><header class="head"><div><h1>我的简历</h1><p>管理你的简历草稿与历史版本</p></div><el-button type="primary" @click="createNew">新建简历</el-button></header><div v-if="loading" class="state">正在加载...</div><div v-else-if="!items.length" class="state">暂无简历，点击右上角开始创建。</div><section v-else class="grid"><article v-for="item in items" :key="item.id"><div class="cover">CV</div><h3>{{ item.title }}</h3><p>{{ item.content?.basics?.name || '尚未填写姓名' }} · {{ item.status==='completed'?'已完成':'草稿' }}</p><small>更新于 {{ formatDate(item.updated_at) }}</small><div class="actions"><el-button @click="$router.push(`/resumes/${item.id}`)">编辑</el-button><el-button type="danger" plain @click="remove(item)">删除</el-button></div></article></section></AppLayout></template>
<script setup>
import{onMounted,ref}from'vue';import{useRouter}from'vue-router';import{ElMessage,ElMessageBox}from'element-plus';import AppLayout from'@/layouts/AppLayout.vue';import{createResume,deleteResume,listResumes}from'@/api/resumes';const router=useRouter(),items=ref([]),loading=ref(true);const load=async()=>{try{items.value=(await listResumes()).data.data.resumes}catch(e){ElMessage.error(e.response?.data?.message||'加载失败')}finally{loading.value=false}};onMounted(load);const createNew=async()=>{const{data}=await createResume({title:'未命名简历'});router.push(`/resumes/${data.data.resume.id}`)};const remove=async item=>{try{await ElMessageBox.confirm(`确定删除“${item.title}”吗？`,'删除简历',{type:'warning'});await deleteResume(item.id);items.value=items.value.filter(x=>x.id!==item.id);ElMessage.success('已删除')}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e.response?.data?.message||'删除失败')}};const formatDate=v=>new Date(v.replace(' ','T')+'Z').toLocaleString('zh-CN')
</script>
<style scoped>.head{display:flex;justify-content:space-between;align-items:center;margin-bottom:26px}.head h1{font-size:29px;font-weight:750}.head p{color:#858b99}.state{display:grid;place-items:center;min-height:360px;background:#fff;border-radius:18px;color:#858b99}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:20px}.grid article{padding:20px;background:#fff;border:1px solid #e7e9ef;border-radius:17px}.cover{height:112px;display:grid;place-items:center;margin-bottom:17px;border-radius:12px;background:linear-gradient(135deg,#eeeaff,#f8f7ff);color:#6d4aff;font-size:30px;font-weight:800}.grid h3{font-size:17px;font-weight:650}.grid p,.grid small{display:block;color:#8a909e}.actions{display:flex;margin-top:18px}.actions button{flex:1}
</style>
